/**
 * Divyanshi Solar — Mobile App API (v1)
 * --------------------------------------
 * Self-contained Express module that serves the Android app used by
 * partners (marketing BDP/DDP/SDP, shop development partners, shop partners),
 * field staff and office admins.
 *
 * Install:  copy to server/mobile-routes.ts, then in server/routes.ts add
 *             import { registerMobileRoutes } from "./mobile-routes";
 *           and call  registerMobileRoutes(app);  anywhere inside registerRoutes().
 *           (It does NOT depend on express-session — it uses its own Bearer tokens —
 *            so placement relative to app.use(session(...)) does not matter.)
 *
 * Tables it owns (created automatically, all prefixed mobile_):
 *   mobile_sessions, mobile_files, mobile_shops, mobile_jobs, mobile_job_reports,
 *   mobile_client_refs
 * Core tables it reads: users, customers, commissions.
 * Core tables it writes: customers (new leads, status change by admin),
 *   users (new shop development partners and shop partners only).
 *
 * Uses raw SQL via the shared pg pool so it keeps working even if the Drizzle
 * schema in shared/schema.ts has drifted from the live database.
 */
import type { Express, Request, Response, NextFunction } from "express";
import express from "express";
import crypto from "crypto";
import zlib from "zlib";
import path from "path";
import fs from "fs";
import bcrypt from "bcrypt";
import multer from "multer";
import { pool } from "./db";
import { generateCustomerCode } from "./storage";

