// Verify role names against the live DB before deploying:
//   sudo -u postgres psql suryamitra_staging -c "SELECT role, count(*) FROM users GROUP BY role;"
// Override without editing code by setting MOBILE_ROLE_MAP in ecosystem.config.cjs, e.g.
//   MOBILE_ROLE_MAP='{"field_engineer":"field"}'   (merged over the defaults below)
export type Persona = "admin" | "marketing" | "shop_dev" | "shop" | "field" | "telecaller";

const DEFAULT_ROLE_PERSONA: Record<string, Persona> = {
  admin: "admin",
  staff_admin: "admin",
  bdp: "marketing",
  ddp: "marketing",
  sdp: "marketing",
  shop_dev: "shop_dev", // role name used by the divyanshisolar.in website
  shop_dev_partner: "shop_dev",
  shop_development_partner: "shop_dev",
  shop: "shop",
  shop_partner: "shop",
  shop_solar_partner: "shop",
  staff: "field",
  field_staff: "field",
  technician: "field",
  employee: "field",
  telecaller: "telecaller",
  tele_caller: "telecaller",
};

function loadRoleMap(): Record<string, Persona> {
  try {
    const extra = process.env.MOBILE_ROLE_MAP ? JSON.parse(process.env.MOBILE_ROLE_MAP) : {};
    return { ...DEFAULT_ROLE_PERSONA, ...extra };
  } catch {
    console.error("[mobile] MOBILE_ROLE_MAP is not valid JSON — using defaults");
    return DEFAULT_ROLE_PERSONA;
  }
}
const ROLE_PERSONA = loadRoleMap();
/** Every role name that maps to a persona (e.g. all role names used for field staff). */
const rolesFor = (p: Persona) => Object.entries(ROLE_PERSONA).filter(([, x]) => x === p).map(([role]) => role);

