/**
 * Monthly incentive: PM Surya Ghar logins with FULL disbursement credited to the person in a month.
 * Above the base target, each one earns perUnit rupees. Override: MOBILE_INCENTIVE='{"telecaller":{"base":2,"perUnit":5000},"field":{"base":3,"perUnit":5000}}'
 */
const INCENTIVE: Record<"telecaller" | "field", { base: number; perUnit: number }> = (() => {
  const base = { telecaller: { base: 2, perUnit: 5000 }, field: { base: 3, perUnit: 5000 } };
  try {
    const o = process.env.MOBILE_INCENTIVE ? JSON.parse(process.env.MOBILE_INCENTIVE) : {};
    return { telecaller: { ...base.telecaller, ...(o.telecaller ?? {}) }, field: { ...base.field, ...(o.field ?? {}) } };
  } catch {
    return base;
  }
})();
/** Performance rule: below `threshold`% daily achievement on `lowDays` working days in a row → notice; `graceDays` to improve. */
const PERF: { threshold: number; lowDays: number; graceDays: number } = (() => {
  const base = { threshold: 60, lowDays: 5, graceDays: 10 };
  try {
    return { ...base, ...(process.env.MOBILE_PERF ? JSON.parse(process.env.MOBILE_PERF) : {}) };
  } catch {
    return base;
  }
})();
