/** People that big / Aata Chakki leads are transferred to (names; matched to their login if they have one). */
const TC_TRANSFER_DEFAULT = (process.env.MOBILE_TRANSFER_TO || "Chandrakant,Sanjay").split(",").map((x) => x.trim()).filter(Boolean);
type TcOutcome = keyof typeof TC_OUTCOMES;
/** Calls that count towards the daily call target: the customer was actually reached and was not a refusal. */
const NOT_COUNTED = ["no_answer", "busy", "not_reachable", "wrong_number", "not_interested", "bill_below_500", "outside_bihar"];
/** Reached, but the customer will go ahead later: always kept as a call-back (default in days). */
const LATER_OUTCOMES: Record<string, number> = { install_later: 30, meter_bill_issue: 10 };
const COUNTED_SQL = (col = "outcome") => `${col} NOT IN (${NOT_COUNTED.map((x) => `'${x}'`).join(",")})`;
/** Customer not reached: the number stays with the caller to try again (retry list, or a chosen call-back time). */
const RETRY_OUTCOMES = ["no_answer", "busy", "not_reachable"];
const NO_CONTACT_SQL = (col = "outcome") => `${col} IN ('no_answer','busy','not_reachable')`;
/** A "not reachable" number stays with the caller to try again, up to this many attempts. */
const RETRY_MAX = Math.max(1, Number(process.env.MOBILE_RETRY_MAX) || 3);
const ymdIST = (d: Date) => new Date(d.getTime() + 5.5 * 3600e3).toISOString().slice(0, 10);
/**
 * Who filled the customer form: the field / sales executive who registered the customer in the app,
 * or the tele-caller whose "Interested" form created it (first one wins).
 */
const FILLED_BY_JOIN = (c = "c") => `LEFT JOIN LATERAL (
    SELECT x.uid, x.kind FROM (
      SELECT a.staff_id AS uid, 'sales' AS kind, a.at FROM mobile_staff_actions a WHERE a.kind = 'customer' AND a.ref_id = ${c}.id
      UNION ALL
      SELECT t.telecaller_id, 'telecaller', t.at FROM tc_calls t
       WHERE t.customer_id = ${c}.id AND t.outcome IN ('survey_scheduled','pm_login','interested','transferred')
    ) x ORDER BY x.at LIMIT 1) fb ON true
  LEFT JOIN users fbu ON fbu.id = fb.uid`;
const FILLED_BY_COLS = `fb.uid AS filled_by_id, fbu.name AS filled_by, fbu.phone AS filled_by_phone, fb.kind AS filled_by_kind`;
const maskPhone = (p: string) => (p && p.length >= 10 ? `${p.slice(0, 2)}XXXXX${p.slice(-3)}` : "XXXXXXXXXX");

/**
 * Daily targets for every Divyanshi employee (field / sales executive). Override without code changes, e.g.
 *   MOBILE_DAILY_TARGETS='{"shopDev":0,"shops":2,"customers":1,"visits":2}'
 * Shop Development Partners are a monthly target (MONTHLY_TARGETS), so the daily one is 0.
 */
const DAILY_TARGETS: { shopDev: number; shops: number; customers: number; visits: number } = (() => {
  const base = { shopDev: 0, shops: 2, customers: 1, visits: 2 };
  try {
    return { ...base, ...(process.env.MOBILE_DAILY_TARGETS ? JSON.parse(process.env.MOBILE_DAILY_TARGETS) : {}) };
  } catch {
    return base;
  }
})();
/** A shop visit counts only when the employee checks in within this distance of the shop's GPS point. */
const VISIT_RADIUS_M = Number(process.env.MOBILE_VISIT_RADIUS_M || 300);

const PUBLIC_BASE_URL = process.env.MOBILE_PUBLIC_BASE_URL || "https://divyanshisolar.in";
const TOKEN_DAYS = 90;
const PRIVATE_DIR = path.join(process.cwd(), "uploads_private", "mobile");

/** Surya Urja Kranti shop commission, Rs per kW. DCR only up to 6 kW; above that always Non-DCR. */
