  /** Admin: every employee — on duty or not, where they are now, km today, today's jobs. */
  r.get(
    "/admin/team",
    requireMobile,
    allow("admin"),
    asyncH(async (_req, res) => {
      const fieldRoles = Object.entries(ROLE_PERSONA).filter(([, p]) => p === "field").map(([role]) => role);
      const staff = await q(
        `SELECT u.id, u.name, u.phone, u.district,
                a.id AS session_id, a.duty_in_at,
                (SELECT min(duty_in_at) FROM mobile_attendance x WHERE x.user_id=u.id AND x.day=(now() AT TIME ZONE '${IST}')::date) AS first_in_today,
                (SELECT max(duty_out_at) FROM mobile_attendance x WHERE x.user_id=u.id AND x.day=(now() AT TIME ZONE '${IST}')::date) AS last_out_today,
                (SELECT count(*)::int FROM mobile_jobs j WHERE j.assignee_id=u.id AND j.status IN ('assigned','in_progress','rejected')) AS open_jobs,
                (SELECT count(*)::int FROM mobile_jobs j WHERE j.assignee_id=u.id AND j.status IN ('assigned','in_progress','rejected') AND j.scheduled_for <= (now() AT TIME ZONE '${IST}')::date) AS due_jobs,
                (SELECT count(*)::int FROM mobile_job_reports r WHERE r.submitted_by=u.id AND (r.created_at AT TIME ZONE current_setting('TimeZone') AT TIME ZONE '${IST}')::date = (now() AT TIME ZONE '${IST}')::date) AS reports_today,
                (SELECT count(*)::int FROM mobile_jobs j WHERE j.assignee_id=u.id AND j.scheduled_for = (now() AT TIME ZONE '${IST}')::date) AS jobs_today,
                (SELECT count(*)::int FROM mobile_jobs j WHERE j.assignee_id=u.id AND j.scheduled_for = (now() AT TIME ZONE '${IST}')::date AND j.status IN ('submitted','approved')) AS jobs_today_done,
                (SELECT count(*)::int FROM mobile_activity x WHERE x.user_id=u.id AND x.day = (now() AT TIME ZONE '${IST}')::date) AS activity_today,
                (SELECT text FROM mobile_activity x WHERE x.user_id=u.id AND x.day = (now() AT TIME ZONE '${IST}')::date ORDER BY at DESC LIMIT 1) AS last_activity
           FROM users u
           LEFT JOIN LATERAL (SELECT id, duty_in_at FROM mobile_attendance m WHERE m.user_id=u.id AND m.duty_out_at IS NULL ORDER BY duty_in_at DESC LIMIT 1) a ON true
          WHERE u.role = ANY($1::text[]) AND u.status <> 'rejected'
          ORDER BY (a.id IS NULL), u.name`,
        [fieldRoles],
      );
      const ids = staff.rows.map((s: any) => s.id);
      const pts = ids.length
        ? (await q(
            `SELECT user_id, lat, lng, accuracy, recorded_at FROM mobile_locations
              WHERE user_id = ANY($1::varchar[]) AND (recorded_at AT TIME ZONE '${IST}')::date = (now() AT TIME ZONE '${IST}')::date
              ORDER BY user_id, recorded_at`,
            [ids],
          )).rows
        : [];
      const lastAny = ids.length
        ? (await q(
            `SELECT DISTINCT ON (user_id) user_id, lat, lng, recorded_at FROM mobile_locations
              WHERE user_id = ANY($1::varchar[]) ORDER BY user_id, recorded_at DESC`,
            [ids],
          )).rows
        : [];
      const byUser: Record<string, any[]> = {};
      for (const p of pts) (byUser[p.user_id] ??= []).push(p);
      const lastBy: Record<string, any> = Object.fromEntries(lastAny.map((p: any) => [p.user_id, p]));
      res.json({
        team: staff.rows.map((s: any) => {
          const last = lastBy[s.id];
          return {
            id: s.id, name: s.name, phone: s.phone, district: s.district,
            onDuty: !!s.session_id, dutyInAt: s.duty_in_at, firstInToday: s.first_in_today, lastOutToday: s.last_out_today,
            kmToday: trailKm(toPts(byUser[s.id] ?? [])),
            last: last ? { lat: Number(last.lat), lng: Number(last.lng), at: last.recorded_at } : null,
            openJobs: s.open_jobs, dueJobs: s.due_jobs, reportsToday: s.reports_today,
            jobsToday: s.jobs_today, jobsTodayDone: s.jobs_today_done, activityToday: s.activity_today, lastActivity: s.last_activity,
          };
        }),
      });
    }),
  );

  /** Admin: one employee's day — duty sessions, route, km, and the jobs assigned to them. */
  r.get(
    "/admin/staff/:id/day",
    requireMobile,
    allow("admin"),
    asyncH(async (req, res) => {
      const id = req.params.id;
      const day = istDay(str(req.query.date, 10));
      const user = (await q(`SELECT id, name, phone, district, role FROM users WHERE id=$1`, [id])).rows[0];
      if (!user) throw httpError(404, "Employee not found");
      const dayExpr = `coalesce($2::date, (now() AT TIME ZONE '${IST}')::date)`;
      const sessions = await q(
        `SELECT id, duty_in_at, duty_out_at, in_lat, in_lng, out_lat, out_lng, km, selfie_id, out_reason
           FROM mobile_attendance WHERE user_id=$1 AND day = ${dayExpr} ORDER BY duty_in_at`,
        [id, day],
      );
      const pts = await dayPoints(id, day);
      const jobs = await q(
        `SELECT j.id, j.job_type, j.status, to_char(j.scheduled_for,'YYYY-MM-DD') AS scheduled_for, j.notes, j.review_note,
                (j.status IN ('assigned','in_progress','rejected') AND j.scheduled_for < (now() AT TIME ZONE '${IST}')::date) AS overdue,
                j.customer_id, coalesce(c.name, j.title) AS customer_name, j.title, c.phone AS customer_phone,
                coalesce(j.address, c.address) AS address, c.district, c.latitude, c.longitude
           FROM mobile_jobs j LEFT JOIN customers c ON c.id = j.customer_id
          WHERE j.assignee_id = $1
            AND (j.status IN ('assigned','in_progress','rejected','submitted') OR j.scheduled_for = ${dayExpr}
                 OR (j.updated_at AT TIME ZONE current_setting('TimeZone') AT TIME ZONE '${IST}')::date = ${dayExpr})
          ORDER BY (j.scheduled_for IS NULL), j.scheduled_for, j.created_at`,
        [id, day],
      );
      const reports = await q(
        `SELECT r.id, r.job_id, r.job_type, r.created_at, r.latitude, r.longitude, coalesce(c.name, j.title) AS customer_name
           FROM mobile_job_reports r JOIN mobile_jobs j ON j.id = r.job_id LEFT JOIN customers c ON c.id = r.customer_id
          WHERE r.submitted_by=$1 AND (r.created_at AT TIME ZONE current_setting('TimeZone') AT TIME ZONE '${IST}')::date = ${dayExpr} ORDER BY r.created_at`,
        [id, day],
      );
      const activity = await q(
        `SELECT x.id, x.at, x.text, x.lat, x.lng, x.photo_id, x.job_id, coalesce(c.name, j.title) AS job_name
           FROM mobile_activity x LEFT JOIN mobile_jobs j ON j.id = x.job_id LEFT JOIN customers c ON c.id = j.customer_id
          WHERE x.user_id=$1 AND x.day = ${dayExpr} ORDER BY x.at`,
        [id, day],
      );
      const trail = toPts(pts);
      res.json({
        activity: activity.rows,
        user,
        date: day ?? (await q(`SELECT to_char((now() AT TIME ZONE '${IST}')::date,'YYYY-MM-DD') AS d`)).rows[0].d,
        sessions: sessions.rows,
        km: trailKm(trail),
        route: thin(trail, 600).map((p) => [Math.round(p.lat * 1e6) / 1e6, Math.round(p.lng * 1e6) / 1e6, p.t]),
        jobs: jobs.rows,
        reports: reports.rows,
      });
    }),
  );

  /** Admin: attendance register for a date range (one row per duty session). */
  r.get(
    "/admin/attendance",
    requireMobile,
    allow("admin"),
    asyncH(async (req, res) => {
      const from = istDay(str(req.query.from, 10));
      const to = istDay(str(req.query.to, 10));
      const { rows } = await q(
        `SELECT a.id, a.user_id, u.name, u.phone, to_char(a.day,'YYYY-MM-DD') AS day, a.duty_in_at, a.duty_out_at, a.km,
                a.in_lat, a.in_lng, a.out_lat, a.out_lng, a.selfie_id
           FROM mobile_attendance a JOIN users u ON u.id = a.user_id
          WHERE a.day BETWEEN coalesce($1::date, (now() AT TIME ZONE '${IST}')::date - 6) AND coalesce($2::date, (now() AT TIME ZONE '${IST}')::date)
          ORDER BY a.day DESC, u.name, a.duty_in_at`,
        [from, to],
      );
      // Open sessions: compute km so far.
      for (const r0 of rows) {
        if (r0.km == null) {
          const pts = await q(`SELECT lat, lng, accuracy, recorded_at FROM mobile_locations WHERE user_id=$1 AND recorded_at >= $2 ORDER BY recorded_at`, [r0.user_id, r0.duty_in_at]);
          r0.km = trailKm(toPts(pts.rows));
          r0.open = true;
        }
      }
      res.json({ rows });
    }),
  );

